const IssuesAndJQLQueriesSchema = z
  .strictObject({
    issueIds: z
      .array(
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({ type: 'integer', format: 'int64', description: 'A list of issue IDs.' }),
      )
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({ description: 'A list of issue IDs.' }),
    jqls: z
      .array(z.string().openapi({ description: 'A list of JQL queries.' }))
      .openapi({ description: 'A list of JQL queries.' }),
  })
  .openapi({ description: 'List of issues and JQL queries.', required: ['issueIds', 'jqls'] })
  .openapi('IssuesAndJQLQueries')

