export const getRestApi3AnnouncementBannerRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/announcementBanner',
  tags: ['Announcement banner'],
  summary: 'Get announcement banner configuration',
  description:
    'Returns the current announcement banner configuration.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getBanner',
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: AnnouncementBannerConfigurationSchema,
          example:
            '{"message":"This is a public, enabled, non-dismissible banner, set using the API","isDismissible":false,"isEnabled":true,"hashId":"9HN2FJK9DM8BHRWERVW3RRTGDJ4G4D5C","visibility":"public"}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example: '"Only admins can read banner configuration."',
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

export const putRestApi3AnnouncementBannerRoute = createRoute({
  method: 'put',
  path: '/rest/api/3/announcementBanner',
  tags: ['Announcement banner'],
  summary: 'Update announcement banner configuration',
  description:
    'Updates the announcement banner configuration.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'setBanner',
  request: {
    body: {
      content: {
        'application/json': {
          schema: AnnouncementBannerConfigurationUpdateSchema,
          example: {
            isDismissible: false,
            isEnabled: true,
            message: 'This is a public, enabled, non-dismissible banner, set using the API',
            visibility: 'public',
          },
        },
      },
      required: true,
    },
  },
  responses: {
    204: {
      description: 'Returned if the request is successful.',
      content: { 'application/json': { schema: z.any() } },
    },
    400: {
      description: 'Returned if an invalid parameter is passed.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example: '"Banner message cannot be null."',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example: '"Only admins can update banner configuration."',
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

export const postRestApi3AppFieldValueRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/app/field/value',
  tags: ['Issue custom field values (apps)'],
  summary: 'Update custom fields',
  description:
    'Updates the value of one or more custom fields on one or more issues. Combinations of custom field and issue should be unique within the request. Custom fields can only be updated by the Forge app that created them.\n\n**[Permissions](#permissions) required:** Only the app that created the custom field can update its values with this operation.',
  operationId: 'updateMultipleCustomFieldValues',
  request: {
    query: z.object({
      generateChangelog: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            description: 'Whether to generate a changelog for this update.',
            in: 'query',
            name: 'generateChangelog',
            schema: { default: true, type: 'boolean' },
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: MultipleCustomFieldValuesUpdateDetailsSchema,
          example: {
            updates: [
              { customField: 'customfield_10010', issueIds: [10010, 10011], value: 'new value' },
              { customField: 'customfield_10011', issueIds: [10010], value: 1000 },
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    204: {
      description: 'Returned if the request is successful.',
      content: { 'application/json': { schema: z.any() } },
    },
    400: { description: 'Returned if the request is invalid.' },
    403: {
      description:
        'Returned if the request is not authenticated as the app that provided all the fields.',
    },
    404: { description: 'Returned if any field is not found.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: [] }],
})

export const getRestApi3AppFieldFieldIdOrKeyContextConfigurationRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/app/field/{fieldIdOrKey}/context/configuration',
  tags: ['Issue custom field configuration (apps)'],
  summary: 'Get custom field configurations',
  description:
    'Returns a [paginated](#pagination) list of configurations for a custom field created by a [Forge app](https://developer.atlassian.com/platform/forge/).\n\nThe result can be filtered by one of these criteria:\n\n *  `id`.\n *  `fieldContextId`.\n *  `issueId`.\n *  `projectKeyOrId` and `issueTypeId`.\n\nOtherwise, all configurations are returned.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). Jira permissions are not required for the Forge app that created the custom field.',
  operationId: 'getCustomFieldConfiguration',
  request: {
    params: z.object({
      fieldIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The ID or key of the custom field, for example `customfield_10000`.',
            in: 'path',
            name: 'fieldIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(
              z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .openapi({ type: 'integer', format: 'int64' }),
            )
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              "The list of configuration IDs. To include multiple configurations, separate IDs with an ampersand: `id=10000&id=10001`. Can't be provided with `fieldContextId`, `issueId`, `projectKeyOrId`, or `issueTypeId`.",
            in: 'query',
            name: 'id',
            schema: {
              items: { format: 'int64', type: 'integer' },
              type: 'array',
              uniqueItems: true,
            },
            required: false,
          },
        }),
      fieldContextId: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(
              z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .openapi({ type: 'integer', format: 'int64' }),
            )
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              "The list of field context IDs. To include multiple field contexts, separate IDs with an ampersand: `fieldContextId=10000&fieldContextId=10001`. Can't be provided with `id`, `issueId`, `projectKeyOrId`, or `issueTypeId`.",
            in: 'query',
            name: 'fieldContextId',
            schema: {
              items: { format: 'int64', type: 'integer' },
              type: 'array',
              uniqueItems: true,
            },
            required: false,
          },
        }),
      issueId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              "The ID of the issue to filter results by. If the issue doesn't exist, an empty list is returned. Can't be provided with `projectKeyOrId`, or `issueTypeId`.",
            in: 'query',
            name: 'issueId',
            schema: { format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      projectKeyOrId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "The ID or key of the project to filter results by. Must be provided with `issueTypeId`. Can't be provided with `issueId`.",
            in: 'query',
            name: 'projectKeyOrId',
            schema: { type: 'string' },
            required: false,
          },
        }),
      issueTypeId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "The ID of the issue type to filter results by. Must be provided with `projectKeyOrId`. Can't be provided with `issueId`.",
            in: 'query',
            name: 'issueTypeId',
            schema: { type: 'string' },
            required: false,
          },
        }),
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 100, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanContextualConfigurationSchema,
          example:
            '{"maxResults":1000,"startAt":0,"total":2,"isLast":true,"values":[{"id":"10000","fieldContextId":"10010"},{"id":"10001","fieldContextId":"10011","configuration":{"minValue":0,"maxValue":10000},"schema":{"properties":{"amount":{"type":"number"},"currency":{"type":"string"}},"required":["amount","currency"]}}]}',
        },
      },
    },
    400: { description: 'Returned if the request is invalid.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: {
      description:
        'Returned if the user is not a Jira admin or the request is not authenticated as from the app that provided the field.',
    },
    404: { description: 'Returned if the custom field is not found.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

