export const postRestApi3CommentListRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/comment/list',
  tags: ['Issue comments'],
  summary: 'Get comments by IDs',
  description:
    'Returns a [paginated](#pagination) list of comments specified by a list of comment IDs.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** Comments are returned where the user:\n\n *  has *Browse projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project containing the comment.\n *  If [issue-level security](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-level security permission to view the issue.\n *  If the comment has visibility restrictions, belongs to the group or has the role visibility is restricted to.',
  operationId: 'getCommentsByIds',
  request: {
    query: z.object({
      expand: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Use [expand](#expansion) to include additional information about comments in the response. This parameter accepts a comma-separated list. Expand options include:\n\n *  `renderedBody` Returns the comment body rendered in HTML.\n *  `properties` Returns the comment's properties.",
            in: 'query',
            name: 'expand',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
    body: {
      description: 'The list of comment IDs.',
      content: {
        'application/json': {
          schema: IssueCommentListRequestBeanSchema,
          example: { ids: [1, 2, 5, 10] },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanCommentSchema,
          example:
            '{"maxResults":1048576,"startAt":0,"total":1,"isLast":true,"values":[{"self":"https://your-domain.atlassian.net/rest/api/3/issue/10010/comment/10000","id":"10000","author":{"self":"https://your-domain.atlassian.net/rest/api/3/user?accountId=5b10a2844c20165700ede21g","accountId":"5b10a2844c20165700ede21g","displayName":"Mia Krystof","active":false},"body":{"type":"doc","version":1,"content":[{"type":"paragraph","content":[{"type":"text","text":"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque eget venenatis elit. Duis eu justo eget augue iaculis fermentum. Sed semper quam laoreet nisi egestas at posuere augue semper."}]}]},"updateAuthor":{"self":"https://your-domain.atlassian.net/rest/api/3/user?accountId=5b10a2844c20165700ede21g","accountId":"5b10a2844c20165700ede21g","displayName":"Mia Krystof","active":false},"created":"2021-01-17T12:34:00.000+0000","updated":"2021-01-18T23:45:00.000+0000","visibility":{"type":"role","value":"Administrators","identifier":"Administrators"}}]}',
        },
      },
    },
    400: { description: 'Returned if the request contains more than 1000 IDs or is empty.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

