export const getRestApi3FieldSearchRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/field/search',
  tags: ['Issue fields'],
  summary: 'Get fields paginated',
  description:
    'Returns a [paginated](#pagination) list of fields for Classic Jira projects. The list can include:\n\n *  all fields\n *  specific fields, by defining `id`\n *  fields that contain a string in the field name or description, by defining `query`\n *  specific fields that contain a string in the field name or description, by defining `id` and `query`\n\nOnly custom fields can be queried, `type` must be set to `custom`.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getFieldsPaginated',
  request: {
    query: z.object({
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 50, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      type: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.enum(['custom', 'system'])),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The type of fields to search.',
            in: 'query',
            name: 'type',
            schema: { items: { enum: ['custom', 'system'], type: 'string' }, type: 'array' },
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()).superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The IDs of the custom fields to return or, where `query` is specified, filter.',
            in: 'query',
            name: 'id',
            schema: { items: { type: 'string' }, type: 'array', uniqueItems: true },
            required: false,
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'String used to perform a case-insensitive partial match with field names or descriptions.',
            in: 'query',
            name: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      orderBy: z
        .enum([
          'contextsCount',
          '-contextsCount',
          '+contextsCount',
          'lastUsed',
          '-lastUsed',
          '+lastUsed',
          'name',
          '-name',
          '+name',
          'screensCount',
          '-screensCount',
          '+screensCount',
          'projectsCount',
          '-projectsCount',
          '+projectsCount',
        ])
        .exactOptional()
        .openapi({
          param: {
            description:
              '[Order](#ordering) the results by a field:\n\n *  `contextsCount` sorts by the number of contexts related to a field\n *  `lastUsed` sorts by the date when the value of the field last changed\n *  `name` sorts by the field name\n *  `screensCount` sorts by the number of screens related to a field',
            in: 'query',
            name: 'orderBy',
            schema: {
              enum: [
                'contextsCount',
                '-contextsCount',
                '+contextsCount',
                'lastUsed',
                '-lastUsed',
                '+lastUsed',
                'name',
                '-name',
                '+name',
                'screensCount',
                '-screensCount',
                '+screensCount',
                'projectsCount',
                '-projectsCount',
                '+projectsCount',
              ],
              type: 'string',
            },
            required: false,
          },
        }),
      expand: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Expand options include:\n\n *  `key` returns the key for each field\n *  `lastUsed` returns the date when the value of the field last changed\n *  `screensCount` returns the number of screens related to a field\n *  `contextsCount` returns the number of contexts related to a field\n *  `isLocked` returns information about whether the field is [locked](https://confluence.atlassian.com/x/ZSN7Og)\n *  `searcherKey` returns the searcher key for each custom field',
            in: 'query',
            name: 'expand',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanFieldSchema,
          example:
            '{"maxResults":50,"startAt":0,"total":2,"isLast":false,"values":[{"id":"customfield_10000","name":"Approvers","schema":{"type":"array","items":"user","custom":"com.atlassian.jira.plugin.system.customfieldtypes:multiuserpicker","customId":10000},"description":"Contains users needed for approval. This custom field was created by Jira Service Desk.","key":"customfield_10000","isLocked":true,"searcherKey":"com.atlassian.jira.plugin.system.customfieldtypes:userpickergroupsearcher","screensCount":2,"contextsCount":2,"lastUsed":{"type":"TRACKED","value":"2019-09-12T10:10:00.934+0000"}},{"id":"customfield_10001","name":"Change reason","schema":{"type":"option","custom":"com.atlassian.jira.plugin.system.customfieldtypes:select","customId":10001},"description":"Choose the reason for the change request","key":"customfield_10001","isLocked":false,"searcherKey":"com.atlassian.jira.plugin.system.customfieldtypes:multiselectsearcher","screensCount":2,"contextsCount":2,"projectsCount":2,"lastUsed":{"type":"NOT_TRACKED"}}]}',
        },
      },
    },
    400: {
      description: 'Returned if the request is invalid.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example: '{"errorMessages":["Only custom fields can be queried."],"errors":{}}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example: '{"errorMessages":["Only Jira administrators can access fields."],"errors":{}}',
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

