export const getRestApi3FieldFieldIdContextRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/field/{fieldId}/context',
  tags: ['Issue custom field contexts'],
  summary: 'Get custom field contexts',
  description:
    'Returns a [paginated](#pagination) list of [ contexts](https://confluence.atlassian.com/adminjiracloud/what-are-custom-field-contexts-991923859.html) for a custom field. Contexts can be returned as follows:\n\n *  With no other parameters set, all contexts.\n *  By defining `id` only, all contexts from the list of IDs.\n *  By defining `isAnyIssueType`, limit the list of contexts returned to either those that apply to all issue types (true) or those that apply to only a subset of issue types (false)\n *  By defining `isGlobalContext`, limit the list of contexts return to either those that apply to all projects (global contexts) (true) or those that apply to only a subset of projects (false).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getContextsForField',
  request: {
    params: z.object({
      fieldId: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the custom field.',
            in: 'path',
            name: 'fieldId',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      isAnyIssueType: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Whether to return contexts that apply to all issue types.',
            in: 'query',
            name: 'isAnyIssueType',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      isGlobalContext: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Whether to return contexts that apply to all projects.',
            in: 'query',
            name: 'isGlobalContext',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      contextId: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(
              z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .openapi({ type: 'integer', format: 'int64' }),
            )
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The list of context IDs. To include multiple contexts, separate IDs with ampersand: `contextId=10000&contextId=10001`.',
            in: 'query',
            name: 'contextId',
            schema: {
              items: { format: 'int64', type: 'integer' },
              type: 'array',
              uniqueItems: true,
            },
            required: false,
          },
        }),
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 50, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanCustomFieldContextSchema,
          example:
            '{"maxResults":100,"startAt":0,"total":2,"isLast":true,"values":[{"id":"10025","name":"Bug fields context","description":"A context used to define the custom field options for bugs.","isGlobalContext":true,"isAnyIssueType":false},{"id":"10026","name":"Task fields context","description":"A context used to define the custom field options for tasks.","isGlobalContext":false,"isAnyIssueType":false}]}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: {
      description: 'Returned if the user does not have the required permissions.',
      content: {},
    },
    404: { description: 'Returned if the custom field was not found.', content: {} },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

