export const getRestApi3GroupBulkRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/group/bulk',
  tags: ['Groups'],
  summary: 'Bulk get groups',
  description:
    'Returns a [paginated](#pagination) list of groups.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'bulkGetGroups',
  request: {
    query: z.object({
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 50, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      groupId: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(z.string().openapi({ example: '3571b9a7-348f-414a-9087-8e1ea03a7df8' }))
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The ID of a group. To specify multiple IDs, pass multiple `groupId` parameters. For example, `groupId=5b10a2844c20165700ede21g&groupId=5b10ac8d82e05b22cc7d4ef5`.',
            in: 'query',
            name: 'groupId',
            schema: {
              example: '3571b9a7-348f-414a-9087-8e1ea03a7df8',
              items: { example: '3571b9a7-348f-414a-9087-8e1ea03a7df8', type: 'string' },
              type: 'array',
              uniqueItems: true,
            },
            'x-showInExample': 'true',
            required: false,
          },
          example: '3571b9a7-348f-414a-9087-8e1ea03a7df8',
        }),
      groupName: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()).superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The name of a group. To specify multiple names, pass multiple `groupName` parameters. For example, `groupName=administrators&groupName=jira-software-users`.',
            in: 'query',
            name: 'groupName',
            schema: { items: { type: 'string' }, type: 'array', uniqueItems: true },
            required: false,
          },
        }),
      accessType: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "The access level of a group. Valid values: 'site-admin', 'admin', 'user'.",
            in: 'query',
            name: 'accessType',
            schema: { type: 'string' },
            required: false,
          },
        }),
      applicationKey: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "The application key of the product user groups to search for. Valid values: 'jira-servicedesk', 'jira-software', 'jira-product-discovery', 'jira-core'.",
            in: 'query',
            name: 'applicationKey',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanGroupDetailsSchema,
          example:
            '{"maxResults":10,"startAt":0,"total":2,"isLast":true,"values":[{"name":"jdog-developers","groupId":"276f955c-63d7-42c8-9520-92d01dca0625"},{"name":"juvenal-bot","groupId":"6e87dc72-4f1f-421f-9382-2fee8b652487"}]}',
        },
      },
    },
    400: { description: 'Returned if the request is not valid.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: {},
    },
    500: {
      description: "Returned if the group with the given access level can't be retrieved.",
      content: {},
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-user'] }],
})

