export const postRestApi3PermissionsCheckRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/permissions/check',
  tags: ['Permissions'],
  summary: 'Get bulk permissions',
  description:
    "Returns:\n\n *  for a list of global permissions, the global permissions granted to a user.\n *  for a list of project permissions and lists of projects and issues, for each project permission a list of the projects and issues a user can access or manipulate.\n\nIf no account ID is provided, the operation returns details for the logged in user.\n\nNote that:\n\n *  Invalid project and issue IDs are ignored.\n *  A maximum of 1000 projects and 1000 issues can be checked.\n *  Null values in `globalPermissions`, `projectPermissions`, `projectPermissions.projects`, and `projectPermissions.issues` are ignored.\n *  Empty strings in `projectPermissions.permissions` are ignored.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) to check the permissions for other users, otherwise none. However, Connect apps can make a call from the app server to the product to obtain permission details for any user, without admin permission. This Connect app ability doesn't apply to calls made using AP.request() in a browser.",
  operationId: 'getBulkPermissions',
  request: {
    body: {
      description: 'Details of the permissions to check.',
      content: {
        'application/json': {
          schema: BulkPermissionsRequestBeanSchema,
          example: {
            accountId: '5b10a2844c20165700ede21g',
            globalPermissions: ['ADMINISTER'],
            projectPermissions: [
              {
                issues: [10010, 10011, 10012, 10013, 10014],
                permissions: ['EDIT_ISSUES'],
                projects: [10001],
              },
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: BulkPermissionGrantsSchema,
          example:
            '{"projectPermissions":[{"permission":"EDIT_ISSUES","issues":[10010,10013,10014],"projects":[10001]}],"globalPermissions":["ADMINISTER"]}',
        },
      },
    },
    400: {
      description:
        'Returned if:\n\n *  `projectPermissions` is provided without at least one project permission being provided.\n *  an invalid global permission is provided in the global permissions list.\n *  an invalid project permission is provided in the project permissions list.\n *  more than 1000 valid project IDs or more than 1000 valid issue IDs are provided.\n *  an invalid account ID is provided.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example: '{"errorMessages":[],"errors":{"PERMISSION_123":"Unrecognized permission"}}',
        },
      },
    },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example:
            '{"errorMessages":["Only Jira administrators can perform this operation."],"errors":{}}',
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: [] }, {}],
})

