export const getRestApi3PrioritySearchRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/priority/search',
  tags: ['Issue priorities'],
  summary: 'Search priorities',
  description:
    'Returns a [paginated](#pagination) list of priorities. The list can contain all priorities or a subset determined by any combination of these criteria:\n\n *  a list of priority IDs. Any invalid priority IDs are ignored.\n *  whether the field configuration is a default. This returns priorities from company-managed (classic) projects only, as there is no concept of default priorities in team-managed projects.\n\n**[Permissions](#permissions) required:** Permission to access Jira.',
  operationId: 'searchPriorities',
  request: {
    query: z.object({
      startAt: z
        .string()
        .default('0')
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: '0', type: 'string' },
            required: false,
          },
        }),
      maxResults: z
        .string()
        .default('50')
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: '50', type: 'string' },
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The list of priority IDs. To include multiple IDs, provide an ampersand-separated list. For example, `id=2&id=3`.',
            in: 'query',
            name: 'id',
            schema: { items: { type: 'string' }, type: 'array' },
            required: false,
          },
        }),
      onlyDefault: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Whether only the default priority is returned.',
            in: 'query',
            name: 'onlyDefault',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanPrioritySchema,
          example:
            '{"maxResults":50,"startAt":0,"total":2,"isLast":true,"values":[{"self":"https://your-domain.atlassian.net/rest/api/3/priority/3","statusColor":"#009900","description":"Major loss of function.","iconUrl":"https://your-domain.atlassian.net/images/icons/priorities/major.png","name":"Major","id":"1","isDefault":true},{"self":"https://your-domain.atlassian.net/rest/api/3/priority/5","statusColor":"#cfcfcf","description":"Very little impact.","iconUrl":"https://your-domain.atlassian.net/images/icons/priorities/trivial.png","name":"Trivial","id":"2","isDefault":false}]}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

