export const postRestApi3ProjectProjectIdOrKeyDeleteRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/project/{projectIdOrKey}/delete',
  tags: ['Projects'],
  summary: 'Delete project asynchronously',
  description:
    'Deletes a project asynchronously.\n\nThis operation is:\n\n *  transactional, that is, if part of the delete fails the project is not deleted.\n *  [asynchronous](#async). Follow the `location` link in the response to determine the status of the task and use [Get task](#api-rest-api-3-task-taskId-get) to obtain subsequent updates.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'deleteProjectAsynchronously',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The project ID or project key (case sensitive).',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    303: {
      description: 'Returned if the request is successful.',
      content: { 'application/json': { schema: TaskProgressBeanObjectSchema } },
    },
    400: { description: 'Returned if the request is not valid.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    404: {
      description:
        'Returned if the project is not found or the user does not have the necessary permission.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }, {}],
})

export const getRestApi3ProjectProjectIdOrKeyFeaturesRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/project/{projectIdOrKey}/features',
  tags: ['Project features'],
  summary: 'Get project features',
  description: 'Returns the list of features for a project.',
  operationId: 'getFeaturesForProject',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The ID or (case-sensitive) key of the project.',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: ContainerForProjectFeaturesSchema,
          example:
            '{"features":[{"projectId":10001,"state":"ENABLED","toggleLocked":true,"feature":"jsw.classic.roadmap","prerequisites":[],"localisedName":"Roadmap","localisedDescription":"Your roadmap is an optimized location to create and manage your epics.","imageUri":"https://jira.atlassian.com/s/sb53l8/b/3/ab8a7691e4738b4f147e293f0864adfd5b8d3c85/_/download/resources/com.atlassian.jira.rest:classic-project-features/simple-roadmap-feature.svg"},{"projectId":10001,"state":"ENABLED","toggleLocked":true,"feature":"jsw.classic.backlog","prerequisites":[],"localisedName":"Backlog","localisedDescription":"Plan and prioritize work in a dedicated space. To enable and configure the backlog for each board, go to board settings.","imageUri":"https://jira.atlassian.com/s/sb53l8/b/3/ab8a7691e4738b4f147e293f0864adfd5b8d3c85/_/download/resources/com.atlassian.jira.rest:classic-project-features/simple-backlog-feature.svg"}]}',
        },
      },
    },
    400: { description: 'Returned if the request is not valid.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: { description: 'Returned if the user does not have the required permissions.' },
    404: { description: 'Returned if the project is not found.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

