export const getRestApi3ProjectProjectIdOrKeyRoleRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/project/{projectIdOrKey}/role',
  tags: ['Project roles'],
  summary: 'Get project roles for project',
  description:
    'Returns a list of [project roles](https://confluence.atlassian.com/x/3odKLg) for the project returning the name and self URL for each role.\n\nNote that all project roles are shared with all projects in Jira Cloud. See [Get all project roles](#api-rest-api-3-role-get) for more information.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for any project on the site or *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getProjectRoles',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The project ID or project key (case sensitive).',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: z.record(z.string(), z.url()),
          example:
            '{"Administrators":"https://your-domain.atlassian.net/rest/api/3/project/MKY/role/10002","Users":"https://your-domain.atlassian.net/rest/api/3/project/MKY/role/10001","Developers":"https://your-domain.atlassian.net/rest/api/3/project/MKY/role/10000"}',
        },
      },
    },
    401: {
      description:
        'Returned if the authentication credentials are incorrect or missing or if the user lacks administrative permissions for the project.',
    },
    404: {
      description:
        'Returned if the project is not found or or if the user does not have administrative permissions for the project.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

export const getRestApi3ProjectProjectIdOrKeyRoleIdRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/project/{projectIdOrKey}/role/{id}',
  tags: ['Project roles'],
  summary: 'Get project role for project',
  description:
    "Returns a project role's details and actors associated with the project. The list of actors is sorted by display name.\n\nTo check whether a user belongs to a role based on their group memberships, use [Get user](#api-rest-api-3-user-get) with the `groups` expand parameter selected. Then check whether the user keys and groups match with the actors returned for the project.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project or *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).",
  operationId: 'getProjectRole',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The project ID or project key (case sensitive).',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The ID of the project role. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    query: z.object({
      excludeInactiveUsers: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Exclude inactive users.',
            in: 'query',
            name: 'excludeInactiveUsers',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: ProjectRoleSchema,
          example:
            '{"self":"https://your-domain.atlassian.net/rest/api/3/project/MKY/role/10360","name":"Developers","id":10360,"description":"A project role that represents developers in a project","actors":[{"id":10240,"displayName":"jira-developers","type":"atlassian-group-role-actor","name":"jira-developers","actorGroup":{"name":"jira-developers","displayName":"jira-developers","groupId":"952d12c3-5b5b-4d04-bb32-44d383afc4b2"}},{"id":10241,"displayName":"Mia Krystof","type":"atlassian-user-role-actor","actorUser":{"accountId":"5b10a2844c20165700ede21g"}}],"scope":{"type":"PROJECT","project":{"id":"10000","key":"KEY","name":"Next Gen Project"}}}',
        },
      },
    },
    400: { description: 'Returned if the request is not valid.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    404: {
      description:
        'Returned if:\n\n *  the project or project role is not found.\n *  the user does not have administrative permission.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

export const putRestApi3ProjectProjectIdOrKeyRoleIdRoute = createRoute({
  method: 'put',
  path: '/rest/api/3/project/{projectIdOrKey}/role/{id}',
  tags: ['Project role actors'],
  summary: 'Set actors for project role',
  description:
    'Sets the actors for a project role for a project, replacing all existing actors.\n\nTo add actors to the project without overwriting the existing list, use [Add actors to project role](#api-rest-api-3-project-projectIdOrKey-role-id-post).\n\n**[Permissions](#permissions) required:** *Administer Projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project or *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'setActors',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The project ID or project key (case sensitive).',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The ID of the project role. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      description:
        "The groups or users to associate with the project role for this project. Provide the user account ID, group name, or group ID. As a group's name can change, use of group ID is recommended.",
      content: {
        'application/json': {
          schema: ProjectRoleActorsUpdateBeanSchema,
          example: {
            categorisedActors: {
              'atlassian-group-role-actor-id': ['952d12c3-5b5b-4d04-bb32-44d383afc4b2'],
              'atlassian-user-role-actor': ['12345678-9abc-def1-2345-6789abcdef12'],
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Returned if the request is successful. The complete list of actors for the project is returned.',
      content: {
        'application/json': {
          schema: ProjectRoleSchema,
          example:
            '{"self":"https://your-domain.atlassian.net/rest/api/3/project/MKY/role/10360","name":"Developers","id":10360,"description":"A project role that represents developers in a project","actors":[{"id":10240,"displayName":"jira-developers","type":"atlassian-group-role-actor","name":"jira-developers","actorGroup":{"name":"jira-developers","displayName":"jira-developers","groupId":"952d12c3-5b5b-4d04-bb32-44d383afc4b2"}},{"id":10241,"displayName":"Mia Krystof","type":"atlassian-user-role-actor","actorUser":{"accountId":"5b10a2844c20165700ede21g"}}],"scope":{"type":"PROJECT","project":{"id":"10000","key":"KEY","name":"Next Gen Project"}}}',
        },
      },
    },
    400: { description: 'Returned if the request is not valid.' },
    401: {
      description:
        'Returned if the authentication credentials are incorrect or missing or if the calling user lacks administrative permissions for the project.',
    },
    404: {
      description:
        'Returned if:\n\n *  the project is not found.\n *  a user or group is not found.\n *  a group or user is not active.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-project'] }, {}],
})

