export const getRestApi3ProjectProjectIdOrKeyVersionRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/project/{projectIdOrKey}/version',
  tags: ['Project versions'],
  summary: 'Get project versions paginated',
  description:
    'Returns a [paginated](#pagination) list of all versions in a project. See the [Get project versions](#api-rest-api-3-project-projectIdOrKey-versions-get) resource if you want to get a full list of versions without pagination.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse Projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project.',
  operationId: 'getProjectVersionsPaginated',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The project ID or project key (case sensitive).',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 50, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      orderBy: z
        .enum([
          'description',
          '-description',
          '+description',
          'name',
          '-name',
          '+name',
          'releaseDate',
          '-releaseDate',
          '+releaseDate',
          'sequence',
          '-sequence',
          '+sequence',
          'startDate',
          '-startDate',
          '+startDate',
        ])
        .exactOptional()
        .openapi({
          param: {
            description:
              '[Order](#ordering) the results by a field:\n\n *  `description` Sorts by version description.\n *  `name` Sorts by version name.\n *  `releaseDate` Sorts by release date, starting with the oldest date. Versions with no release date are listed last.\n *  `sequence` Sorts by the order of appearance in the user interface.\n *  `startDate` Sorts by start date, starting with the oldest date. Versions with no start date are listed last.',
            in: 'query',
            name: 'orderBy',
            schema: {
              enum: [
                'description',
                '-description',
                '+description',
                'name',
                '-name',
                '+name',
                'releaseDate',
                '-releaseDate',
                '+releaseDate',
                'sequence',
                '-sequence',
                '+sequence',
                'startDate',
                '-startDate',
                '+startDate',
              ],
              type: 'string',
            },
            required: false,
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter the results using a literal string. Versions with matching `name` or `description` are returned (case insensitive).',
            in: 'query',
            name: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      status: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A list of status values used to filter the results by version status. This parameter accepts a comma-separated list. The status values are `released`, `unreleased`, and `archived`.',
            in: 'query',
            name: 'status',
            schema: { type: 'string' },
            required: false,
          },
        }),
      expand: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Expand options include:\n\n *  `issuesstatus` Returns the number of issues in each status category for each version.\n *  `operations` Returns actions that can be performed on the specified version.',
            in: 'query',
            name: 'expand',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanVersionSchema,
          example:
            '{"self":"https://your-domain.atlassian.net/rest/api/3/project/PR/version?startAt=0&maxResults=2","nextPage":"https://your-domain.atlassian.net/rest/api/3/project/PR/version?startAt=2&maxResults=2","maxResults":2,"startAt":0,"total":7,"isLast":false,"values":[{"self":"https://your-domain.atlassian.net/rest/api/3/version/10000","id":"10000","description":"An excellent version","name":"New Version 1","archived":false,"released":true,"releaseDate":"2010-07-06","overdue":true,"userReleaseDate":"6/Jul/2010","projectId":10000},{"self":"https://your-domain.atlassian.net/rest/api/3/version/10010","id":"10010","description":"Minor Bugfix version","name":"Next Version","archived":false,"released":false,"overdue":false,"projectId":10000,"issuesStatusForFixVersion":{"unmapped":0,"toDo":10,"inProgress":20,"done":100}}]}',
        },
      },
    },
    404: {
      description:
        'Returned if the project is not found or the user does not have permission to view it.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

