export const getRestApi3ResolutionSearchRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/resolution/search',
  tags: ['Issue resolutions'],
  summary: 'Search resolutions',
  description:
    'Returns a [paginated](#pagination) list of resolutions. The list can contain all resolutions or a subset determined by any combination of these criteria:\n\n *  a list of resolutions IDs.\n *  whether the field configuration is a default. This returns resolutions from company-managed (classic) projects only, as there is no concept of default resolutions in team-managed projects.\n\n**[Permissions](#permissions) required:** Permission to access Jira.',
  operationId: 'searchResolutions',
  request: {
    query: z.object({
      startAt: z
        .string()
        .default('0')
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: '0', type: 'string' },
            required: false,
          },
        }),
      maxResults: z
        .string()
        .default('50')
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: '50', type: 'string' },
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The list of resolutions IDs to be filtered out',
            in: 'query',
            name: 'id',
            schema: { items: { type: 'string' }, type: 'array' },
            required: false,
          },
        }),
      onlyDefault: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'When set to true, return default only, when IDs provided, if none of them is default, return empty page. Default value is false',
            in: 'query',
            name: 'onlyDefault',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanResolutionJsonBeanSchema,
          example:
            '{"maxResults":50,"startAt":0,"total":1,"isLast":true,"values":[{"id":"10001","description":"This is what it is supposed to do.","name":"Works as designed","isDefault":true}]}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

