export const getRestApi3StatusesRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/statuses',
  tags: ['Status'],
  summary: 'Bulk get statuses',
  description:
    'Returns a list of the statuses specified by one or more status IDs.\n\n**[Permissions](#permissions) required:**\n\n *  *Administer projects* [project permission.](https://confluence.atlassian.com/x/yodKLg)\n *  *Administer Jira* [project permission.](https://confluence.atlassian.com/x/yodKLg)',
  operationId: 'getStatusesById',
  request: {
    query: z.object({
      expand: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Expand options include:\n\n *  `usages` Returns the project and issue types that use the status in their workflow.',
            in: 'query',
            name: 'expand',
            schema: { type: 'string' },
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The list of status IDs. To include multiple IDs, provide an ampersand-separated list. For example, id=10000&id=10001.\n\nMin items `1`, Max items `50`',
            in: 'query',
            name: 'id',
            schema: { items: { type: 'string' }, type: 'array' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: z.array(JiraStatusSchema),
          example:
            '[{"id":"1000","name":"Finished","statusCategory":"DONE","scope":{"type":"PROJECT","project":{"id":"1"}},"description":"The issue is resolved","usages":[{"project":{"id":"1"},"issueTypes":["10002"]}]}]',
        },
      },
    },
    400: { description: 'Returned if the request is not valid.' },
    401: {
      description:
        "Returned if the authentication credentials are incorrect or missing, or the caller doesn't have permissions to perform the operation.",
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

