export const getRestApi3WebhookRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/webhook',
  tags: ['Webhooks'],
  summary: 'Get dynamic webhooks for app',
  description:
    'Returns a [paginated](#pagination) list of the webhooks registered by the calling app.\n\n**[Permissions](#permissions) required:** Only [Connect](https://developer.atlassian.com/cloud/jira/platform/#connect-apps) and [OAuth 2.0](https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps) apps can use this operation.',
  operationId: 'getDynamicWebhooksForApp',
  request: {
    query: z.object({
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 100, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanWebhookSchema,
          example:
            '{"maxResults":3,"startAt":0,"total":3,"isLast":true,"values":[{"id":10000,"jqlFilter":"project = PRJ","fieldIdsFilter":["summary","customfield_10029"],"events":["jira:issue_updated","jira:issue_created"],"expirationDate":"2019-06-01T12:42:30.000+0000"},{"id":10001,"jqlFilter":"issuetype = Bug","events":["jira:issue_created"],"expirationDate":"2019-06-01T12:42:30.000+0000"},{"id":10002,"jqlFilter":"project = PRJ","issuePropertyKeysFilter":["my-issue-property-key"],"events":["issue_property_set"],"expirationDate":"2019-06-01T12:42:30.000+0000"}]}',
        },
      },
    },
    400: {
      description: 'Returned if the request is invalid.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
    403: {
      description: "Returned if the caller isn't an app.",
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work', 'manage:jira-webhook'] }],
})

export const postRestApi3WebhookRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/webhook',
  tags: ['Webhooks'],
  summary: 'Register dynamic webhooks',
  description:
    'Registers webhooks.\n\n**NOTE:** for non-public OAuth apps, webhooks are delivered only if there is a match between the app owner and the user who registered a dynamic webhook.\n\n**[Permissions](#permissions) required:** Only [Connect](https://developer.atlassian.com/cloud/jira/platform/#connect-apps) and [OAuth 2.0](https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps) apps can use this operation.',
  operationId: 'registerDynamicWebhooks',
  request: {
    body: {
      content: {
        'application/json': {
          schema: WebhookRegistrationDetailsSchema,
          example: {
            url: 'https://your-app.example.com/webhook-received',
            webhooks: [
              {
                events: ['jira:issue_created', 'jira:issue_updated'],
                fieldIdsFilter: ['summary', 'customfield_10029'],
                jqlFilter: 'project = PROJ',
              },
              {
                events: ['jira:issue_deleted'],
                jqlFilter: 'project IN (PROJ, EXP) AND status = done',
              },
              {
                events: ['issue_property_set'],
                issuePropertyKeysFilter: ['my-issue-property-key'],
                jqlFilter: 'project = PROJ',
              },
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: ContainerForRegisteredWebhooksSchema,
          example:
            '{"webhookRegistrationResult":[{"createdWebhookId":1000},{"errors":["The clause watchCount is unsupported"]},{"createdWebhookId":1001}]}',
        },
      },
    },
    400: {
      description: 'Returned if the request is invalid.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
    403: {
      description: "Returned if the caller isn't an app.",
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work', 'manage:jira-webhook'] }],
})

