export const getRestApi3WorkflowTransitionsTransitionIdPropertiesRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/workflow/transitions/{transitionId}/properties',
  tags: ['Workflow transition properties'],
  summary: 'Get workflow transition properties',
  description:
    'Returns the properties on a workflow transition. Transition properties are used to change the behavior of a transition. For more information, see [Transition properties](https://confluence.atlassian.com/x/zIhKLg#Advancedworkflowconfiguration-transitionproperties) and [Workflow properties](https://confluence.atlassian.com/x/JYlKLg).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getWorkflowTransitionProperties',
  request: {
    params: z.object({
      transitionId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description:
              'The ID of the transition. To get the ID, view the workflow in text mode in the Jira administration console. The ID is shown next to the transition.',
            in: 'path',
            name: 'transitionId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    query: z.object({
      includeReservedKeys: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Some properties with keys that have the *jira.* prefix are reserved, which means they are not editable. To include these properties in the results, set this parameter to *true*.',
            in: 'query',
            name: 'includeReservedKeys',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
      key: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The key of the property being returned, also known as the name of the property. If this parameter is not specified, all properties on the transition are returned.',
            in: 'query',
            name: 'key',
            schema: { type: 'string' },
            required: false,
          },
        }),
      workflowName: z
        .string()
        .openapi({
          param: {
            description: 'The name of the workflow that the transition belongs to.',
            in: 'query',
            name: 'workflowName',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workflowMode: z
        .enum(['live', 'draft'])
        .default('live')
        .exactOptional()
        .openapi({
          param: {
            description:
              'The workflow status. Set to *live* for active and inactive workflows, or *draft* for draft workflows.',
            in: 'query',
            name: 'workflowMode',
            schema: { default: 'live', enum: ['live', 'draft'], type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '200 response',
      content: {
        'application/json': {
          schema: WorkflowTransitionPropertySchema,
          example:
            '[{"key":"jira.i18n.title","value":"some.title","id":"jira.i18n.title"},{"key":"jira.permission","value":"createissue","id":"jira.permission"}]',
        },
      },
    },
    400: { description: 'Returned if the request is invalid.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: { description: 'Returned if the user does not have admin permission' },
    404: { description: 'Returned if the workflow transition or property is not found.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

