export const getRestApi3WorkflowschemeProjectRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/workflowscheme/project',
  tags: ['Workflow scheme project associations'],
  summary: 'Get workflow scheme project associations',
  description:
    'Returns a list of the workflow schemes associated with a list of projects. Each returned workflow scheme includes a list of the requested projects associated with it. Any team-managed or non-existent projects in the request are ignored and no errors are returned.\n\nIf the project is associated with the `Default Workflow Scheme` no ID is returned. This is because the way the `Default Workflow Scheme` is stored means it has no ID.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getWorkflowSchemeProjectAssociations',
  request: {
    query: z.object({
      projectId: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(
              z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .openapi({ type: 'integer', format: 'int64', example: 10010 }),
            )
            .min(1)
            .max(100)
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .openapi({
          param: {
            description:
              'The ID of a project to return the workflow schemes for. To include multiple projects, provide an ampersand-Jim: oneseparated list. For example, `projectId=10000&projectId=10001`.',
            in: 'query',
            name: 'projectId',
            required: true,
            schema: {
              items: { example: 10010, format: 'int64', type: 'integer' },
              maxItems: 100,
              minItems: 1,
              type: 'array',
              uniqueItems: true,
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: ContainerOfWorkflowSchemeAssociationsSchema,
          example:
            '{"values":[{"projectIds":["10010","10020"],"workflowScheme":{"id":101010,"name":"Example workflow scheme","description":"The description of the example workflow scheme.","defaultWorkflow":"jira","issueTypeMappings":{"10000":"scrum workflow","10001":"builds workflow"},"self":"https://your-domain.atlassian.net/rest/api/3/workflowscheme/101010"}}]}',
        },
      },
    },
    400: { description: 'Returned if the request is invalid.', content: {} },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: {},
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

