export const getRestApi3WorklogDeletedRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/worklog/deleted',
  tags: ['Issue worklogs'],
  summary: 'Get IDs of deleted worklogs',
  description:
    'Returns a list of IDs and delete timestamps for worklogs deleted after a date and time.\n\nThis resource is paginated, with a limit of 1000 worklogs per page. Each page lists worklogs from oldest to youngest. If the number of items in the date range exceeds 1000, `until` indicates the timestamp of the youngest item on the page. Also, `nextPage` provides the URL for the next page of worklogs. The `lastPage` parameter is set to true on the last page of worklogs.\n\nThis resource does not return worklogs deleted during the minute preceding the request.\n\n**[Permissions](#permissions) required:** Permission to access Jira.',
  operationId: 'getIdsOfWorklogsDeletedSince',
  request: {
    query: z.object({
      since: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The date and time, as a UNIX timestamp in milliseconds, after which deleted worklogs are returned.',
            in: 'query',
            name: 'since',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: ChangedWorklogsSchema,
          example:
            '{"values":[{"worklogId":103,"updatedTime":1438013671562,"properties":[]},{"worklogId":104,"updatedTime":1438013672165,"properties":[]},{"worklogId":105,"updatedTime":1438013693136,"properties":[]}],"since":1438013671562,"until":1438013693136,"self":"https://your-domain.atlassian.net/api/~ver~/worklog/deleted?since=1438013671562","nextPage":"https://your-domain.atlassian.net/api/~ver~/worklog/deleted?since=1438013693136","lastPage":true}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

